import {
  useCreateConversation,
  useGetAllConversations,
} from "@/lib/react-query/chat/chat";
import cookieService from "@/utils/cookieService";
import { ChevronDown, MoreHorizontal, Plus } from "lucide-react";
import { useState, useMemo } from "react";
import { toast } from "react-toastify";
import { IUserSearch } from "@/interfaces/main";
import { useGetUserSearch } from "@/lib/react-query/main";

interface SideBarProps {
  setSelectedConversationId: (id: string) => void;
}
function SideBar({ setSelectedConversationId }: SideBarProps) {
  const token = cookieService.getToken()!;
  const {
    data: conversations,
    isLoading,
    refetch: refetchConversations,
  } = useGetAllConversations(token);
  const [isAddingChat, setIsAddingChat] = useState(false);
  const { mutate: createNewConversation } = useCreateConversation();

  // State to store the search query for conversations
  const [searchQuery, setSearchQuery] = useState<string>("");

  // State and hook for searching new users
  const [userSearchQuery, setUserSearchQuery] = useState("");
  const { data: users, isLoading: isLoadingUsers } = useGetUserSearch(
    token,
    userSearchQuery
  );

  const handleUserSelect = (user: IUserSearch) => {
    setIsAddingChat(false);
    setUserSearchQuery("");
    if (user.details.conversation!==null) {
      setSelectedConversationId(user.details.conversation);
    } else {
      createNewConversation(
        { token, role: user.type, userId: user.details.id },
        {
          onSuccess: async (newConversation) => {
            await refetchConversations();

            setSelectedConversationId(newConversation.data.id);
          },
          onError: (error) => {
            console.error("Failed to create conversation:", error);
            toast.error("Failed to start a new chat. Please try again.");
          },
        }
      );
    }
  };

  // Filtered conversations based on search query
  const filteredConversations = useMemo(() => {
    if (!conversations?.data) {
      return [];
    }
    return conversations.data.filter((conv) =>
      conv.participant?.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [conversations, searchQuery]);

  return (
    <div className="col-span-1 bg-[#FFFFFF] shadow-md rounded-md relative h-[400px] overflow-hidden">
      {/* Main View: Conversation List */}
      <div
        className={`h-full flex flex-col transform transition-transform duration-300 ease-in-out ${
          isAddingChat ? "-translate-x-full" : "translate-x-0"
        }`}
      >
        <div className="px-4 pt-4">
          <input
            type="search"
            placeholder="🔍 Search Here..."
            className="w-full p-3 bg-[#F0FEFC] shadow-sm rounded-md text-center focus:outline-none placeholder:text-black placeholder:text-center"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <hr className="mt-4" />
        <div className="flex justify-center items-center p-4 gap-4">
          <div className="flex gap-1 items-center">
            {conversations && conversations.data.length>0 &&(
              <>
              <h3 className="font-bold font-sora text-[#194C80] text-lg">
              All Chats
            </h3>
            <ChevronDown size={25} className="text-[#194C80] cursor-pointer" />
              </>
            )}
          </div>
          <button
            onClick={() => setIsAddingChat(true)}
            className="text-[#194C80] hover:text-main border border-[#194D80] rounded-md p-1 hover:border-main transition-colors duration-300"
          >
            <Plus size={25} />
          </button>
        </div>
        {/* conversation list */}
        <div className="flex-grow overflow-y-auto py-5">
          {isLoading ? (
            <p className="text-black text-base text-center">Loading...</p>
          ) : filteredConversations.length === 0 && !searchQuery ? (
            <div className="flex flex-col items-center justify-center gap-2">
             <svg width="150" height="100" viewBox="0 0 360 281" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
<rect width="360" height="281" fill="url(#pattern0_3807_525)"/>
<defs>
<pattern id="pattern0_3807_525" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlinkHref="#image0_3807_525" transform="matrix(0.00249377 0 0 0.00319489 -0.144638 0)"/>
</pattern>
<image id="image0_3807_525" width="500" height="500" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
</defs>
</svg>

              <p className="text-[#194D80] text-lg font-sora font-bold text-center">
                No Conversation .... Yet
              </p>
            </div>
          ) : filteredConversations.length === 0 && searchQuery ? (
            <p className="text-black text-base text-center">
              No Matching Conversations.
            </p>
          ) : (
            <div className="flex flex-col gap-2">
              {filteredConversations.map((conv) => (
                <div
                  key={conv.conversation_id}
                  onClick={() =>
                    setSelectedConversationId(conv.conversation_id)
                  }
                  className="flex flex-row items-center justify-center gap-4 cursor-pointer hover:bg-[#F0FEFC] py-1 transition-colors duration-200"
                >
                  <div className="w-10 h-10 rounded-full flex-shrink-0">
                    <img
                      className="w-full h-full rounded-full object-cover"
                      src={
                        conv.participant.profile_image ||
                        "/images/profile-avatar.webp"
                      }
                      alt="user-image"
                    />
                  </div>
                  <div className="flex flex-col justify-center gap-1">
                    <div className="flex flex-row items-start gap-5">
                      <h4 className="font-sora font-semibold text-[16px] text-black capitalize">
                        {conv.participant?.name}
                      </h4>
                      <div>
                        <MoreHorizontal size={22} />
                      </div>
                    </div>
                    <p className="font-sora text-sm">
                      {conv.last_message?.data?.body || ""}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Add New Chat View */}
      <div
        className={`absolute top-0 left-0 w-full h-full bg-white flex flex-col transform transition-transform duration-300 ease-in-out ${
          isAddingChat ? "translate-x-0" : "translate-x-full"
        }`}
      >
        {/*
                <div className="flex items-center p-4 bg-main text-white flex-shrink-0">
                    <button onClick={() => { setIsAddingChat(false); setUserSearchQuery(""); }} className="mr-4">
                        <ArrowLeft size={24} />
                    </button>
                    <h3 className="text-xl font-bold">New Chat</h3>
                </div> 
                 */}
        <div className="p-4 flex-shrink-0">
          <input
            type="search"
            placeholder="🔍 Search For The Name...."
            value={userSearchQuery}
            onChange={(e) => setUserSearchQuery(e.target.value)}
            className="w-full p-3 bg-[#F0FEFC] shadow-sm rounded-md text-center focus:outline-none placeholder:text-black placeholder:text-center"
          />
        </div>
        <hr />
        <div className="flex justify-center items-center p-4">
          <h3 className="font-bold font-sora text-[#194C80] text-lg capitalize">
            Contact them on chat...
          </h3>
        </div>
        <div className="flex-grow overflow-y-auto px-2">
          {isLoadingUsers ? (
            <p className="text-center text-gray-500 pt-4">Searching...</p>
          ) : users && users.length > 0 ? (
            users.map((user: IUserSearch) => (
              <div
                key={user.details.id}
                onClick={() => handleUserSelect(user)}
                className="flex justify-center items-center gap-4 p-1 hover:bg-[#194D80] group cursor-pointer rounded-md transition-colors"
              >
                <div className="w-10 h-10 rounded-full overflow-hidden flex-shrink-0">
                  <img
                    src={
                      user.details.profile_image ||
                      "/images/profile-avatar.webp"
                    }
                    alt={user.details.name}
                    className="w-full h-full object-cover"
                  />
                </div>
                <div className="flex flex-col">
                  <span className="font-semibold text-gray-800 group-hover:text-white ">
                    {user.details.name}
                  </span>
                  <span className="text-gray-500 text-xs group-hover:text-white">
                    {user.type}
                  </span>
                </div>
              </div>
            ))
          ) : (
            <p className="text-center text-gray-500 pt-4">
              {userSearchQuery
                ? "No users found."
                : "Start typing to search for users."}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default SideBar;
